
import os,base64,io,time,subprocess,sys
os.environ["HF_HOME"]="/kaggle/temp/hf"
os.environ["PYTORCH_CUDA_ALLOC_CONF"]="expandable_segments:True"
subprocess.run([sys.executable,"-m","pip","install","-q","-U","diffusers","transformers","accelerate","sentencepiece","imageio","imageio-ffmpeg"],check=True)
import torch
from PIL import Image
from diffusers import LTXImageToVideoPipeline
from diffusers.utils import export_to_video
IMGS={"v3_girl_sad": "", "v3_nani_calm": "", "v3_girl_happy": "", "v3_nani_happy": ""}
SHOTS=[[1, "v3_girl_sad", "A cute young girl in a pink headscarf looks sadly into the camera with teary eyes, then glances down and sighs, her shoulders rise and fall, small natural head movements, she blinks slowly, tears glisten.", 21], [2, "v3_nani_calm", "A sweet elderly grandmother in a floral headscarf smiles warmly and nods gently, slowly tilts her head with loving compassion, blinks softly, subtle breathing.", 22], [3, "v3_girl_sad", "The cute girl in the pink headscarf looks up at the camera with pleading teary eyes, her chin trembles, she sniffles and tilts her head slightly, blinks slowly.", 23], [4, "v3_nani_calm", "The grandmother looks into the camera with calm confidence, gives one slow reassuring nod, a soft smile, her eyes shine, gentle breathing.", 24], [5, "v3_girl_sad", "The cute girl takes a deep breath, her eyes close for a moment, then she opens them with quiet determination, lifts her chin slightly and gives a small nod.", 25], [6, "v3_girl_happy", "The cute girl bursts with joy, bouncing slightly with excitement, a big joyful smile, sparkling eyes, her head bobs happily, she blinks.", 26], [7, "v3_nani_happy", "The grandmother smiles proudly with tearful happy eyes, slowly nods, gentle breathing, a soft blink.", 27]]
t0=time.time()
pipe=LTXImageToVideoPipeline.from_pretrained("Lightricks/LTX-Video",torch_dtype=torch.bfloat16)
pipe.enable_model_cpu_offload(); pipe.vae.enable_tiling()
print("loaded",time.time()-t0,flush=True)
neg="worst quality, inconsistent motion, blurry, jittery, distorted, morphing face, changing identity, text, watermark, mouth wide open"
for n,name,motion,seed in SHOTS:
    img=Image.open(io.BytesIO(base64.b64decode(IMGS[name]))).convert("RGB")
    prompt=motion+" Clearly visible natural head and body movement, gentle cinematic feel, mouth closed or barely moving, 3D animated film, warm golden light"
    t1=time.time()
    out=pipe(image=img,prompt=prompt,negative_prompt=neg,width=480,height=832,num_frames=81,num_inference_steps=30,guidance_scale=5.0,generator=torch.Generator().manual_seed(seed)).frames[0]
    export_to_video(out,f"/kaggle/working/shot{n}.mp4",fps=24)
    print("shot",n,"done",time.time()-t1,flush=True)
print("ALL DONE")
